
SELECT * FROM (SELECT "QUICKSQL$PAGE".*, ROWNUM "QUICKSQL$ROWNUM" FROM (SELECT "T0"."ID", "T0"."CUSTOMERNAME", "T0"."CUSTOMERID", "T0"."AMOUNT", "T0"."STATE", "T0"."CREATEDAT", "T0"."PAIDAT", "T0"."NOTE" FROM "QUICKSQLORDER" "T0" ORDER BY "T0"."ID" ASC) "QUICKSQL$PAGE" WHERE ROWNUM <= (:p0 + :p1)) WHERE "QUICKSQL$ROWNUM" > :p2
